package com.utegear.dto.catalog;

import com.fasterxml.jackson.databind.JsonNode; import com.utegear.entity.*; import java.math.BigDecimal; import java.time.OffsetDateTime; import java.util.List; import java.util.Map; import org.springframework.data.domain.Page;
public final class ProductDtos {
 private ProductDtos(){}
 public record Image(Long id,String secureUrl,String altText,boolean primary,int sortOrder){static Image from(ProductImage i){return new Image(i.getId(),i.getSecureUrl(),i.getAltText(),i.isPrimary(),i.getSortOrder());}}
 public record Variant(Long id,String sku,Map<String,String> optionValues,boolean isDefault,BigDecimal priceAdjustment,BigDecimal effectivePrice,long totalStock,boolean inStock){static Variant from(ProductVariant v,BigDecimal base){BigDecimal price=base.add(v.getPriceAdjustment());return new Variant(v.getId(),v.getSku(),v.getOptionValues(),v.isDefault(),v.getPriceAdjustment(),price,0,false);}}
 public record Summary(Long id,String name,String slug,CategorySummary category,BrandSummary brand,BigDecimal basePrice,BigDecimal salePrice,BigDecimal effectivePrice,Image primaryImage,Long defaultVariantId,int variantCount,long totalStock,boolean inStock,List<Variant> variants){public static Summary from(Product p){List<Variant> variants=p.getVariants().stream().filter(ProductVariant::isActive).map(v->Variant.from(v,p.getEffectivePrice())).toList();Image primary=p.getImages().stream().filter(ProductImage::isPrimary).findFirst().map(Image::from).orElse(null);Long defaultId=p.getVariants().stream().filter(ProductVariant::isDefault).map(ProductVariant::getId).findFirst().orElse(null);return new Summary(p.getId(),p.getName(),p.getSlug(),CategorySummary.from(p.getCategory()),p.getBrand()==null?null:BrandSummary.from(p.getBrand()),p.getBasePrice(),p.getSalePrice(),p.getEffectivePrice(),primary,defaultId,variants.size(),0,false,variants);}}
 public record Detail(Long id,String name,String slug,String description,JsonNode specifications,CategorySummary category,BrandSummary brand,BigDecimal basePrice,BigDecimal salePrice,BigDecimal effectivePrice,Long defaultVariantId,int variantCount,long totalStock,boolean inStock,List<Image> images,List<Variant> variants,OffsetDateTime createdAt,OffsetDateTime updatedAt){public static Detail from(Product p){Summary s=Summary.from(p);return new Detail(s.id(),s.name(),s.slug(),p.getDescription(),p.getSpecifications(),s.category(),s.brand(),s.basePrice(),s.salePrice(),s.effectivePrice(),s.defaultVariantId(),s.variantCount(),s.totalStock(),s.inStock(),p.getImages().stream().map(Image::from).toList(),s.variants(),p.getCreatedAt(),p.getUpdatedAt());}}
 public record ProductPage(List<Summary> content,int page,int size,long totalElements,int totalPages,boolean first,boolean last,boolean empty){public static ProductPage from(Page<Product> p){return new ProductPage(p.getContent().stream().map(Summary::from).toList(),p.getNumber(),p.getSize(),p.getTotalElements(),p.getTotalPages(),p.isFirst(),p.isLast(),p.isEmpty());}}
}
